<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import CityAnalyticsDrawer from './CityAnalyticsDrawer.vue';
import { cityApi, err, text, time } from '../city-analytics';
const props=defineProps<{modelValue:boolean;kind:'evaluation'|'credit'}>();
const emit=defineEmits<{'update:modelValue':[value:boolean];changed:[]}>();
const session=useSessionStore(),loading=ref(false),saving=ref(false),error=ref(''),data=ref<any>(),form=ref<any>(),restored=ref(false);
const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)}),canEdit=computed(()=>session.user?.permissions.includes('analytics:evaluation:config'));
const path=computed(()=>`${cityApi}/${props.kind==='credit'?'credit':'evaluations'}/rules`);
const storageKey=computed(()=>`wrc-city-rules-${session.user?.id}-${props.kind}`);
const options=[{key:'accidentCount',name:'已确认事故数',dimension:'SAFETY'},{key:'violationCount',name:'已确认违规数',dimension:'COMPLIANCE'},{key:'onlineRate',name:'有效上报在线率',dimension:'OPERATION'},{key:'rectificationRate',name:'到期整改完成率',dimension:'COMPLIANCE'}];
const weight=computed(()=>form.value?.indicators?.reduce((s:number,i:any)=>s+Number(i.weight??0),0)??0);
async function load(){loading.value=true;error.value='';try{data.value=await api(path.value);form.value=JSON.parse(JSON.stringify(data.value));restored.value=false;try{const saved=JSON.parse(localStorage.getItem(storageKey.value)??'null');if(saved?.version===data.value.version){form.value=saved;restored.value=true;}}catch{}}catch(e){error.value=err(e);}finally{loading.value=false;}}
function addIndicator(){const v=options.find(o=>!form.value.indicators.some((i:any)=>i.metricKey===o.key));if(v)form.value.indicators.push({metricKey:v.key,name:v.name,dimension:v.dimension,weight:10,rules:[{minValue:0,maxValue:null,score:100,label:'有效记录'}]});}
function metricChanged(item:any){const o=options.find(o=>o.key===item.metricKey);if(o){item.name=o.name;item.dimension=o.dimension;}}
function addBand(item:any){const last=item.rules.at(-1);if(last)last.maxValue=(last.minValue??0)+1;item.rules.push({minValue:last?.maxValue??0,maxValue:null,score:60,label:'其他区间'});}
async function save(){if(!form.value||saving.value)return;if(props.kind==='evaluation'&&Math.abs(weight.value-100)>.001)return ElMessage.warning('启用指标权重合计须为100%');try{await ElMessageBox.confirm('新版本仅用于后续创建的评价或信用事项，已留存结果继续保留原规则。确认发布生效？','发布规则',{confirmButtonText:'发布生效',cancelButtonText:'取消'});}catch{return;}saving.value=true;error.value='';try{await api(path.value,{method:'POST',body:JSON.stringify(props.kind==='credit'?{expectedVersion:data.value.version,bands:form.value.bands}:{expectedVersion:data.value.version,name:form.value.name,indicators:form.value.indicators})});try{localStorage.removeItem(storageKey.value);}catch{}ElMessage.success('规则已发布生效');emit('changed');await load();}catch(e){error.value=err(e);}finally{saving.value=false;}}
watch(()=>props.modelValue,v=>{if(v)void load();});
watch(form,v=>{if(v&&!loading.value&&canEdit.value)try{localStorage.setItem(storageKey.value,JSON.stringify(v));}catch{}},{deep:true});
</script>
<template><CityAnalyticsDrawer v-model="visible" :title="kind==='credit'?'信用规则':'评价规则'" width="760px">
 <div v-if="error" class="ca-form-error" role="alert">{{error}} <el-button v-if="!form" link @click="load">重试</el-button></div><el-skeleton v-if="loading" :rows="10" animated/>
 <template v-else-if="form"><p class="ca-note">当前版本：{{data.versionLabel}}<template v-if="data.active"> · {{data.publishedBy}} · {{time(data.effectiveAt)}}</template></p><el-alert v-if="!data.active" type="info" :closable="false" title="规则尚未生效。请核对指标或信用标准，发布后用于后续办理。"/><p v-if="restored" class="ca-note">已恢复尚未发布的规则草稿。</p>
 <template v-if="kind==='evaluation'"><el-form label-position="top"><el-form-item label="规则名称"><el-input v-model="form.name" :disabled="!canEdit" maxlength="120" aria-label="规则名称"/></el-form-item></el-form><p class="ca-note">当前权重合计：<strong :class="{'ca-warning':weight!==100}">{{weight}}%</strong>。评分区间从0开始连续覆盖，最后区间不设上限；缺失数据不默认计分。</p>
 <article v-for="(item,index) in form.indicators" :key="index" class="ca-rule"><div class="ca-rule-head"><el-select v-model="item.metricKey" :disabled="!canEdit" :aria-label="`指标${index+1}`" @change="metricChanged(item)"><el-option v-for="o in options" :key="o.key" :label="o.name" :value="o.key" :disabled="form.indicators.some((x:any,i:number)=>i!==index&&x.metricKey===o.key)"/></el-select><el-select v-model="item.dimension" :disabled="!canEdit" :aria-label="`指标${index+1}维度`"><el-option label="安全表现" value="SAFETY"/><el-option label="合规情况" value="COMPLIANCE"/><el-option label="运行表现" value="OPERATION"/></el-select><label>权重 <el-input-number v-model="item.weight" :min=".01" :max="100" :disabled="!canEdit" :aria-label="`指标${index+1}权重`" controls-position="right" style="width:100px"/> %</label><el-button v-if="canEdit" link type="danger" @click="form.indicators.splice(index,1)">移除指标</el-button></div><div class="ca-band ca-muted"><span>下限（含）</span><span>上限（不含）</span><span>指标得分</span><span>区间说明</span></div><div v-for="(band,b) in item.rules" :key="b" class="ca-band"><el-input-number v-model="band.minValue" :min="0" :disabled="!canEdit" :aria-label="`指标${index+1}区间${b+1}下限`" :controls="false"/><el-input-number v-model="band.maxValue" :min="0" :disabled="!canEdit" placeholder="不限" :aria-label="`指标${index+1}区间${b+1}上限`" :controls="false"/><el-input-number v-model="band.score" :min="0" :max="100" :disabled="!canEdit" :aria-label="`指标${index+1}区间${b+1}得分`" :controls="false"/><div style="display:flex;gap:4px"><el-input v-model="band.label" :disabled="!canEdit" :aria-label="`指标${index+1}区间${b+1}说明`"/><el-button v-if="canEdit&&item.rules.length>1" link type="danger" :aria-label="`移除指标${index+1}区间${b+1}`" @click="item.rules.splice(b,1)">×</el-button></div></div><el-button v-if="canEdit" link type="primary" @click="addBand(item)">添加评分区间</el-button></article><el-button v-if="canEdit&&form.indicators.length<options.length" @click="addIndicator">添加指标</el-button></template>
 <template v-else><p class="ca-note">平台信用初始分100分，等级为A（≥90）、B（≥75）、C（≥60）、D（&lt;60）。仅已确认的事故、违规或检查事项可计入，不根据原始告警自动扣分。</p><table class="ca-detail-table"><thead><tr><th>事项程度</th><th>扣分值</th><th>修复等待期（天）</th></tr></thead><tbody><tr v-for="b in form.bands" :key="b.key"><td>{{text(b.key)}}</td><td><el-input-number v-model="b.points" :min="1" :max="100" :disabled="!canEdit" :aria-label="`${text(b.key)}扣分值`"/></td><td><el-input-number v-model="b.repairDays" :min="0" :max="3650" :disabled="!canEdit" :aria-label="`${text(b.key)}修复等待期`"/></td></tr></tbody></table><p class="ca-note">满足日期后仍须核对整改事实和修复材料。修复保留原事项，并记录恢复分值及办理人。此处为平台规则配置，不代替公共社会信用认定。</p></template>
 </template><template #footer><el-button @click="visible=false">关闭</el-button><el-button v-if="canEdit" type="primary" :loading="saving" :disabled="loading||!form" @click="save">发布新版本</el-button></template>
</CityAnalyticsDrawer></template>
